        private void Frmreportall_Load(object sender, EventArgs e)
        {
            Class1 objclass = new Class1();
            con = new SqlConnection(objclass.arun_con());

            con.Open();
            cmd = new SqlCommand("select cc,comp,year_start,year_end,Regno from setup");
            cmd.Connection = con;
            dr1 = cmd.ExecuteReader();
            while (dr1.Read())
            {
                cbopcode.Text = dr1.GetValue(4).ToString();
                //this.txtcompid.Text = dr.GetValue(0).ToString();
                //label4.Text = dr.GetValue(1).ToString();
                //dtfrom.Text = dr.GetValue(2).ToString();

            }
            dr1.Close();


            da = new SqlDataAdapter("select  pcode,patient_name from Patient_Master order by pcode", con);
            ds5 = new DataSet();
            da.Fill(ds5);
            for (int i = 0; i < ds5.Tables[0].Rows.Count; i++)
            {
 
                this.cbopcode.Items.Add(ds5.Tables[0].Rows[i][0].ToString().Trim() );
             
            
            }
            da.Dispose();
            da = new SqlDataAdapter("select patient_name,date_exam from patient_master where pcode='" + cbopcode.Text + "' order by pcode", con);
            ds5 = new DataSet();
            da.Fill(ds5);
           cboname.Text = ds5.Tables[0].Rows[0][0].ToString();
          txtdate.Text = ds5.Tables[0].Rows[0][1].ToString();
          
            da.Dispose();
            
            
            da = new SqlDataAdapter("select cc,comp,address,year_start,year_end,pathologist,biochemist,telphoneno,email,cstno,address1,faxno from company", con);
            ds2 = new DataSet();
            da.Fill(ds2);
